<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';require_once __DIR__.'/tag_engine.php';require_once __DIR__.'/federation_lib.php';require_once __DIR__.'/maintenance.php';
$logged=!empty($_SESSION['loggedin']);$user=(string)($_SESSION['name']??'');$uid=(int)($_SESSION['id']??0);$q=trim((string)($_GET['q']??''));$type=strtolower(trim((string)($_GET['type']??'all')));if($type==='media')$type='post';
$view=max(-256,min(256,(int)($_GET['view']??0)));$scope='all';if(isset($_GET['scope'])&&in_array(trim((string)$_GET['scope']),['global','public','private'],true))$scope=trim((string)$_GET['scope']);elseif(isset($_GET['view'])&&!isset($_GET['all_scopes']))$scope=tt_scope_from_slider($view);
$db=tt_db_open(true);$adsReady=tt_ad_schema_ready($db);try{tt_opportunistic_maintenance($db);tt_federation_tick($db);}catch(Throwable $e){}
$where=[];$params=[];$types='';if($logged){[$v,$vp,$vt]=tt_visible_where('p');$where[]=$v;$params=array_merge($params,$vp);$types.=$vt;}else{$where[]="p.`scope` IN ('global','public','public ')";}
if($q!==''){$where[]='(p.`title` LIKE ? OR p.`content` LIKE ? OR p.`tags` LIKE ? OR p.`name` LIKE ? OR EXISTS (SELECT 1 FROM `tag_index` ti WHERE ti.`post_id`=p.`id` AND (ti.`tag` LIKE ? OR ti.`raw_token` LIKE ?)))';$like='%'.$q.'%';for($i=0;$i<6;$i++)$params[]=$like;$types.='ssssss';}
if($scope!=='all'&&in_array($scope,['global','public','private'],true)){if($scope==='private'&&!$logged)$scope='public';$where[]='TRIM(p.`scope`)=?';$params[]=$scope;$types.='s';}
if($type==='post'){$where[]="LOWER(TRIM(p.`type`)) IN ('post','media')";}elseif($type!=='all'&&in_array($type,['ad','message','event','group','forum'],true)){$where[]='p.`type`=?';$params[]=$type;$types.='s';}
if($adsReady){$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`file`,p.`tags`,p.`name`,p.`comments`,p.`scope`,p.`recipients`,p.`type`,p.`votes`,p.`federated`,p.`origin_host`,a.`id` AS owner_account_id,pa.`mime_type` AS attachment_mime,ab.`id` AS boost_id,COALESCE(ab.`budget_mills`-ab.`spent_mills`,0) AS boost_remaining FROM `posts` p LEFT JOIN `accounts` a ON a.`username`=p.`name` LEFT JOIN `post_attachments` pa ON pa.`post_id`=p.`id` LEFT JOIN `ad_boosts` ab ON ab.`id`=(SELECT MAX(ab2.`id`) FROM `ad_boosts` ab2 WHERE ab2.`post_id`=p.`id` AND ab2.`status`=\'active\' AND ab2.`budget_mills`>ab2.`spent_mills`) WHERE '.implode(' AND ',$where).' ORDER BY (COALESCE(ab.`budget_mills`-ab.`spent_mills`,0)>0) DESC,COALESCE(ab.`budget_mills`-ab.`spent_mills`,0) DESC,p.`dt` DESC,p.`id` DESC LIMIT 250';}else{$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`file`,p.`tags`,p.`name`,p.`comments`,p.`scope`,p.`recipients`,p.`type`,p.`votes`,p.`federated`,p.`origin_host`,a.`id` AS owner_account_id,pa.`mime_type` AS attachment_mime,NULL AS boost_id,0 AS boost_remaining FROM `posts` p LEFT JOIN `accounts` a ON a.`username`=p.`name` LEFT JOIN `post_attachments` pa ON pa.`post_id`=p.`id` WHERE '.implode(' AND ',$where).' ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 250';}$s=tt_prepare($db,$sql);if($types!=='')$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();if($q!==''){foreach($rows as &$r)$r['_score']=tt_tag_relevance($q,(string)$r['tags']);unset($r);usort($rows,fn($a,$b)=>(($b['_score']<=>$a['_score'])?:strcmp((string)$b['dt'],(string)$a['dt'])));} $rows=array_slice($rows,0,100);
// One Karma read for the visible result set. Karma belongs to posts and every saved rater perspective remains editable.
$ratingState=[];if($rows){$ids=implode(',',array_map(fn($r)=>(int)$r['id'],$rows));$rr=$db->query('SELECT `post_id`,`voter_account_id`,`perspective` FROM `post_ratings` WHERE `post_id` IN ('.$ids.')');while($rr&&($x=$rr->fetch_assoc())){$pid=(int)$x['post_id'];if(!isset($ratingState[$pid]))$ratingState[$pid]=['n'=>0,'sum'=>0.0,'mine'=>0];$ratingState[$pid]['n']++;$ratingState[$pid]['sum']+=tt_perspective_normalized((int)$x['perspective']);if((int)$x['voter_account_id']===$uid)$ratingState[$pid]['mine']=(int)$x['perspective'];}if($rr)$rr->free();}
foreach($rows as &$r){$pid=(int)$r['id'];$x=$ratingState[$pid]??['n'=>0,'sum'=>0.0,'mine'=>0];$r['_rating']=$x['n']>0?(int)round(max(-1,min(1,$x['sum']/$x['n']))*256):0;$r['_rating_count']=$x['n'];$r['_my_rating']=$x['mine'];}unset($r);$replyAffinity=tt_reply_affinity_for_view($view,$scope==='all');$rows=tt_sort_reply_threads($rows,$replyAffinity);$db->close();
?>
